//! The golden photos' built-in lens corrections against RAWmakase's own record
//! of them. Ours.
//!
//! Argentum's readers of the camera's own lens correction are copied from
//! RAWmakase's (engine `rm_lens_builtin/`, one file per make). RAWmakase
//! records what its decoder reads from each raw.pixls.us file
//! (`tests/corpus/dataset/pixls-decode.json`, MIT), so on the golden photos
//! ours must read the same tables, part by part. The record is
//! `src-tauri/tests/look/rm_lens_baselines.tsv`, generated by
//! `node scripts/rawmakase-lens-baselines.mjs <release>`, which leaves out the
//! fields our `LensCorrection` does not carry and names them on its Source
//! line. Our `always` is ours alone and not compared.

use argentum_engine::rm_lens_builtin::{LensCorrection, Radial};

const TABLE: &str = include_str!("../../../tests/look/rm_lens_baselines.tsv");

/// Equal within this much, relative: the records are f32 written as JSON.
const TOLERANCE: f32 = 1e-6;

/// RAWmakase's record for the file with this sha256: `None` when the table
/// has no row for it, `Some(None)` when it records no correction.
pub fn recorded(sha256: &str) -> Option<Option<LensCorrection>> {
    rows().find(|(sha, _)| *sha == sha256).map(|(_, lens)| lens)
}

fn rows() -> impl Iterator<Item = (&'static str, Option<LensCorrection>)> {
    TABLE
        .lines()
        .filter(|line| !line.starts_with('#') && !line.is_empty())
        .map(|line| {
            let mut fields = line.splitn(3, '\t');
            let (_id, sha, json) = (fields.next(), fields.next(), fields.next());
            let lens = serde_json::from_str(json.unwrap_or("null"))
                .unwrap_or_else(|e| panic!("rm_lens_baselines.tsv, {line:.40}: {e}"));
            (sha.unwrap_or_default(), lens)
        })
}

/// Does our reading of a file match RAWmakase's record of it? `Ok` when the
/// table has no row for the file.
pub fn check(sha256: &str, ours: Option<&LensCorrection>) -> Result<(), String> {
    let Some(theirs) = recorded(sha256) else {
        return Ok(());
    };
    match (theirs.as_ref(), ours) {
        (None, None) => Ok(()),
        (Some(t), None) => Err(format!("RAWmakase reads {}, ours nothing", t.source)),
        (None, Some(o)) => Err(format!("ours reads {}, RAWmakase nothing", o.source)),
        (Some(t), Some(o)) => {
            let mut differ = Vec::new();
            if t.source != o.source {
                differ.push(format!("source {:?} against {:?}", o.source, t.source));
            }
            if t.default_on != o.default_on {
                differ.push(format!(
                    "default_on {} against {}",
                    o.default_on, t.default_on
                ));
            }
            for (part, ours, theirs) in [
                ("distortion", o.distortion.as_ref(), t.distortion.as_ref()),
                ("vignetting", o.vignetting.as_ref(), t.vignetting.as_ref()),
                (
                    "red",
                    o.chromatic.as_ref().map(|c| &c[0]),
                    t.chromatic.as_ref().map(|c| &c[0]),
                ),
                (
                    "blue",
                    o.chromatic.as_ref().map(|c| &c[1]),
                    t.chromatic.as_ref().map(|c| &c[1]),
                ),
            ] {
                if let Some(d) = radial_differs(ours, theirs) {
                    differ.push(format!("{part}: {d}"));
                }
            }
            if differ.is_empty() {
                Ok(())
            } else {
                Err(differ.join("; "))
            }
        }
    }
}

fn radial_differs(ours: Option<&Radial>, theirs: Option<&Radial>) -> Option<String> {
    let close = |a: &[f32], b: &[f32]| {
        a.len() == b.len()
            && a.iter()
                .zip(b)
                .all(|(x, y)| (x - y).abs() <= TOLERANCE * y.abs().max(1.0))
    };
    match (ours, theirs) {
        (None, None) => None,
        (Some(_), None) => Some("ours has a table, RAWmakase none".into()),
        (None, Some(_)) => Some("RAWmakase has a table, ours none".into()),
        (Some(o), Some(t)) => {
            (!close(&o.knots, &t.knots) || !close(&o.values, &t.values)).then(|| {
                format!(
                    "{} points against {}, or other values",
                    o.values.len(),
                    t.values.len()
                )
            })
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Every row reads as a correction our code knows, and the table holds the
    /// golden photos it says it holds.
    #[test]
    fn the_record_reads_as_our_corrections() {
        let rows: Vec<_> = rows().collect();
        assert_eq!(rows.len(), 10);
        assert_eq!(rows.iter().filter(|(_, lens)| lens.is_some()).count(), 8);
        let samples = include_str!("../../../tests/look/samples.tsv");
        for (sha, _) in &rows {
            assert!(samples.contains(sha), "{sha} is not a golden photo");
        }
    }

    #[test]
    fn a_reading_is_compared_part_by_part() {
        let (sha, lens) = rows()
            .find(|(_, lens)| lens.as_ref().is_some_and(|l| l.chromatic.is_some()))
            .unwrap();
        let lens = lens.unwrap();
        assert_eq!(check(sha, Some(&lens)), Ok(()));
        assert!(check(sha, None).is_err());

        let mut off = lens.clone();
        off.chromatic.as_mut().unwrap()[1].values[0] += 0.001;
        let said = check(sha, Some(&off)).unwrap_err();
        assert!(said.contains("blue") && !said.contains("red"), "{said}");

        // Our own `always` is not RAWmakase's to have.
        let mut ours = lens.clone();
        ours.always = Some(argentum_engine::rm_lens_builtin::Parts::ALL);
        assert_eq!(check(sha, Some(&ours)), Ok(()));
    }

    #[test]
    fn a_file_the_record_does_not_hold_is_not_judged() {
        assert_eq!(check("not-a-golden-photo", None), Ok(()));
    }
}
